const raw = $json;
const clean = (value, max = 500) => String(value ?? '').normalize('NFKC').replace(/[\u0000-\u001F\u007F]/g, ' ').replace(/\s+/g, ' ').trim().slice(0, max);
const name = clean(raw.Name, 120);
const email = clean(raw.Email, 254).toLowerCase();
const org = clean(raw.Org, 160);
const context = clean(raw.Context, 2000);
const inputStatus = clean(raw.Status, 40).toLowerCase().replace(/[^a-z0-9_-]/g, '_');
const draftId = clean(raw.DraftId, 200);
const priorKey = clean(raw.IdempotencyKey, 100);
const errors = [];
if (!name) errors.push('name_required');
if (!org) errors.push('org_required');
if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) errors.push('email_invalid');
const placeholderPattern = /(?:\[[^\]]+\]|\{\{[^}]+\}\}|<[^>]+>|\b(?:todo|tbd|replace\s+(?:me|this|with)|your\s+(?:name|organization))\b)/i;
if ([name, email, org, context].some((value) => placeholderPattern.test(value))) errors.push('placeholder_detected');
const injectionPattern = /(?:ignore|disregard|override|reveal|repeat).{0,40}(?:instruction|prompt|system|policy)|(?:system|developer)\s+message|jailbreak|act\s+as/i;
const promptInjectionDetected = injectionPattern.test(context);
const keySource = [email, name.toLowerCase(), org.toLowerCase()].join('|');
let hash = 2166136261;
for (const character of keySource) { hash ^= character.charCodeAt(0); hash = Math.imul(hash, 16777619); }
const idempotencyKey = `diaspora-dna-${(hash >>> 0).toString(16).padStart(8, '0')}`;
let status = 'ready';
let ready = true;
let guardReason = '';
if (errors.length) { status = 'validation_failed'; ready = false; guardReason = errors.join(','); }
else if (promptInjectionDetected) { status = 'prompt_injection_blocked'; ready = false; guardReason = 'untrusted_context_instruction'; }
else if (draftId || (priorKey && priorKey === idempotencyKey) || ['draft_created', 'success', 'completed'].includes(inputStatus)) { status = 'duplicate'; ready = false; guardReason = 'already_processed'; }
else if (inputStatus !== 'ready') { status = 'not_ready'; ready = false; guardReason = 'status_must_be_ready'; }
return { json: { ...raw, name, email, org, context, inputStatus, validationErrors: errors, promptInjectionDetected, idempotencyKey, ready, status, guardReason } };

