const output = String($json.output ?? '').trim();
const placeholderPattern = /(?:\[[^\]]+\]|\{\{[^}]+\}\}|<[^>]+>|\b(?:todo|tbd|replace\s+(?:me|this|with)|your\s+(?:name|organization))\b)/i;
const leakedInstructionPattern = /(?:system|developer)\s+(?:message|prompt)|ignore\s+(?:all|previous)\s+instructions/i;
const outputErrors = [];
if (output.length < 40) outputErrors.push('draft_too_short');
if (output.length > 10000) outputErrors.push('draft_too_long');
if (placeholderPattern.test(output)) outputErrors.push('placeholder_detected');
if (leakedInstructionPattern.test(output)) outputErrors.push('instruction_leak_detected');
return { json: { ...$('Normalize and Validate').item.json, draftBody: output, outputErrors, outputValid: outputErrors.length === 0, status: outputErrors.length === 0 ? 'draft_validated' : 'draft_content_failed' } };
